TypeScript example:
import { Redwood } from 'redwood-sdk'
const client = new Redwood({ transport: { minSockets: 2, maxSockets: 128, keepAliveMs: 60000, requestTimeoutMs: 30000 } })
const stream = client.chat.stream({ conversationId })
for await (const chunk of stream) { console.log(chunk) }

Go example:
import (
  "time"
  "github.com/redwood/redwood-go"
)
client := redwood.NewClient(redwood.Config{
  HTTPClient: &http.Client{
    Transport: &http.Transport{MaxIdleConns: 200, IdleConnTimeout: 60 * time.Second},
    Timeout: 30 * time.Second,
  },
})
// use client.StreamChat(...) with provided context for backpressure
